const hashToken=v=>crypto.createHash('sha256').update(v).digest('hex');
function randomToken(){return crypto.randomBytes(32).toString('hex')}
function base32Decode(s){const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';let bits='',out=[];for(const ch of String(s||'').replace(/=+$/,'').toUpperCase()){const i=alphabet.indexOf(ch);if(i<0)continue;bits+=i.toString(2).padStart(5,'0')}for(let i=0;i+8<=bits.length;i+=8)out.push(parseInt(bits.slice(i,i+8),2));return Buffer.from(out)}
function totp(secret,time=Math.floor(Date.now()/1000),step=30){const key=base32Decode(secret),counter=Math.floor(time/step);const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(counter));const h=crypto.createHmac('sha1',key).update(b).digest();const o=h[h.length-1]&15;const code=((h.readUInt32BE(o)&0x7fffffff)%1000000).toString().padStart(6,'0');return code}
function verifyTotp(secret,code){const now=Math.floor(Date.now()/1000);return [totp(secret,now-30),totp(secret,now),totp(secret,now+30)].includes(String(code||''))}
