app.patch('/api/crm/leads/:id/stage',auth,async(req,res)=>{const l=await one('SELECT * FROM leads WHERE id=$1 AND agency_id=$2',[req.params.id,req.user.agency_id]);if(!l||(req.user.role==='customer'&&Number(l.customer_id)!==Number(req.user.customer_id)))return res.status(404).json({error:'Lead not found'});const pipe=l.pipeline_id?await one('SELECT stages FROM pipelines WHERE id=$1 AND agency_id=$2 AND customer_id=$3',[l.pipeline_id,req.user.agency_id,l.customer_id]):null;const stage=String(req.body.stage||'New').trim();if(pipe&&!((pipe.stages||[]).map(String)).includes(stage))return res.status(400).json({error:'Stage is not part of this pipeline'});const r=(await q('UPDATE leads SET stage=$1,updated_at=now() WHERE id=$2 RETURNING *',[stage,l.id])).rows[0];res.json(r)});
app.get('/api/crm/export',auth,async(req,res)=>{if(!allowed(req.user,'crm'))return res.status(403).json({error:'Access denied'});const params=[req.user.agency_id];let where='WHERE l.agency_id=$1';let n=2;if(req.user.role==='customer'){where+=' AND l.customer_id=$'+n;params.push(req.user.customer_id);n++}else if(req.query.customer_id){where+=' AND l.customer_id=$'+n;params.push(Number(req.query.customer_id));n++}if(req.query.pipeline_id){where+=' AND l.pipeline_id=$'+n;params.push(Number(req.query.pipeline_id));n++}const rows=(await q(`SELECT l.id,l.name,l.phone,l.email,l.customer_id,l.pipeline_id,l.stage,l.source,p.name AS pipeline_name FROM leads l LEFT JOIN pipelines p ON p.id=l.pipeline_id ${where} ORDER BY l.id DESC`,params)).rows;const headers=['Lead ID','Lead Name','Mobile','Email','Customer ID','Pipeline','Stage','Source'];const csv=[headers,...rows.map(r=>[r.id,r.name,r.phone,r.email,r.customer_id,r.pipeline_name||'',r.stage,r.source])].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="Apexjov_Leads_Export.csv"');res.send('\ufeff'+csv)});
