// V28 production module API layer: remaining portal modules use server-side PostgreSQL records.
const WORKSPACE_MODULES=new Set(['campaigns','lead_automation','sales','operations','inbox','calendar','tasks','referrals','notifications','domains','seo','meta_ads','google_ads','whatsapp','websites','funnels','chatbot','invoices','subscriptions','payments']);
const BILLING_MODULES=new Set(['invoices','subscriptions','payments']);
function scopedCustomerId(req,body={}){ if(req.user.role==='customer') return Number(req.user.customer_id)||null; return body.customer_id?Number(body.customer_id):null; }
async function assertCustomerScope(req,cid){ if(!cid)return true; const c=await one('SELECT id FROM customers WHERE id=$1 AND agency_id=$2',[cid,req.user.agency_id]); return !!c; }
function workspaceRows(req,module){
  const base=req.user.role==='customer' ? 'SELECT * FROM workspace_records WHERE agency_id=$1 AND customer_id=$2 AND module=$3 ORDER BY id DESC' : 'SELECT * FROM workspace_records WHERE agency_id=$1 AND module=$2 ORDER BY id DESC';
  const params=req.user.role==='customer' ? [req.user.agency_id,req.user.customer_id,module] : [req.user.agency_id,module];
  return q(base,params);
}
function shapeRecord(r){ return {id:r.id,payload:r.payload,status:r.status,customer_id:r.customer_id,created_at:r.created_at,updated_at:r.updated_at}; }
for(const module of WORKSPACE_MODULES){
  app.get('/api/'+module,auth,async(req,res)=>{
    if(!allowed(req.user,module) && !allowed(req.user,module==='meta_ads'?'campaigns':module)) return res.status(403).json({error:'Access denied'});
    try{const rows=(await workspaceRows(req,module)).rows; if(BILLING_MODULES.has(module)) return res.json(rows.map(r=>({...r.payload,id:r.id,customer_id:r.customer_id,status:r.status}))); res.json(rows.map(shapeRecord));}catch(e){res.status(500).json({error:e.message})}
  });
  app.post('/api/'+module,auth,async(req,res)=>{
    if(!allowed(req.user,module) && !allowed(req.user,module==='meta_ads'?'campaigns':module)) return res.status(403).json({error:'Access denied'});
    try{const cid=scopedCustomerId(req,req.body||{}); if(cid && !(await assertCustomerScope(req,cid)))return res.status(400).json({error:'Customer not in your agency'}); const payload={...(req.body||{})}; const row=(await q('INSERT INTO workspace_records(agency_id,customer_id,module,payload,status,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[req.user.agency_id,cid,module,JSON.stringify(payload),String(payload.status||'Active'),req.user.id])).rows[0]; await audit(req,'create',module,row.id,payload); res.status(201).json(BILLING_MODULES.has(module)?{...row.payload,id:row.id,customer_id:row.customer_id,status:row.status}:shapeRecord(row));}catch(e){res.status(400).json({error:e.message})}
  });
}
app.patch('/api/workspace/:module/:id',auth,async(req,res)=>{
  const {module,id}=req.params; if(!WORKSPACE_MODULES.has(module))return res.status(404).json({error:'Module not found'}); if(!allowed(req.user,module)&&!allowed(req.user,module==='meta_ads'?'campaigns':module))return res.status(403).json({error:'Access denied'});
  try{const existing=await one('SELECT * FROM workspace_records WHERE id=$1 AND agency_id=$2 AND module=$3',[id,req.user.agency_id,module]); if(!existing || (req.user.role==='customer'&&Number(existing.customer_id)!==Number(req.user.customer_id)))return res.status(404).json({error:'Record not found'}); const payload={...(existing.payload||{}),...(req.body||{})}; const row=(await q('UPDATE workspace_records SET payload=$1,status=$2,updated_at=now() WHERE id=$3 RETURNING *',[JSON.stringify(payload),String(payload.status||existing.status||'Active'),id])).rows[0]; await audit(req,'update',module,id,payload); res.json(BILLING_MODULES.has(module)?{...row.payload,id:row.id,customer_id:row.customer_id,status:row.status}:shapeRecord(row));}catch(e){res.status(400).json({error:e.message})}
});
