app.post('/api/users',auth,async(req,res)=>{if(!['agency_owner','agency_admin'].includes(req.user.role))return res.status(403).json({error:'Platform Owner creates agencies only; Agency Owner manages its own team.'});const {name,email,password,role='agency_staff',permissions=[]}=req.body||{};const agencyId=req.user.agency_id;if(!agencyId)return res.status(400).json({error:'Agency workspace is required'});if(!name||!email)return res.status(400).json({error:'Name and email required'});if(!password||String(password).length<8)return res.status(400).json({error:'Password must be at least 8 characters'});if(!['agency_admin','agency_staff'].includes(role))return res.status(400).json({error:'Only Admin or Staff roles can be created here'});if(req.user.role==='agency_admin'&&role!=='agency_staff')return res.status(403).json({error:'Only Agency Owner can approve Admin access'});const safePermissions=Array.isArray(permissions)?permissions.filter(p=>!['agencies','plans_pricing','training_reset'].includes(p)):[];const hash=bcrypt.hashSync(password,10);try{const u=await one('INSERT INTO users(name,email,password_hash,role,agency_id,permissions) VALUES($1,$2,$3,$4,$5,$6) RETURNING id,name,email,role,agency_id,active,permissions',[String(name).trim(),String(email).trim().toLowerCase(),hash,role,agencyId,JSON.stringify(safePermissions)]);await audit(req,'create','user',u.id,{role,agency_id:agencyId,permissions:safePermissions});res.status(201).json({...u,temporary_password:password})}catch(e){res.status(400).json({error:e.message})}});
app.patch('/api/customers/:id',auth,async(req,res)=>{if(!allowed(req.user,'customers'))return res.status(403).json({error:'Access denied'});const c=await one('SELECT * FROM customers WHERE id=$1 AND agency_id=$2',[req.params.id,req.user.agency_id]);if(!c)return res.status(404).json({error:'Customer not found'});const b=req.body||{};const fields=['status','business_name','name','phone','industry','address','city','state','pincode','website_url','instagram_url','facebook_url','logo_url','owner_photo_url','billing_name','pan','gstin','gst_status','billing_address','notes'];const sets=[];const vals=[];for(const f of fields){if(Object.prototype.hasOwnProperty.call(b,f)){sets.push(`${f}=$${vals.length+1}`);vals.push(String(b[f]??'').trim())}}if(!sets.length)return res.json(c);vals.push(c.id);const r=await one(`UPDATE customers SET ${sets.join(', ')} WHERE id=$${vals.length} RETURNING *`,vals);await audit(req,'update','customer',c.id,{fields:sets.map(x=>x.split('=')[0])});res.json(r)});
