function graphBase(base, version){return `${String(base||'https://graph.facebook.com').replace(/\/$/,'')}/${version||'v24.0'}`;}
app.get('/api/integrations/status',auth,(req,res)=>{
  res.json({
    meta_ads:{configured:Boolean(process.env.META_ACCESS_TOKEN),ad_account_configured:Boolean(process.env.META_AD_ACCOUNT_ID),mode:'server_api'},
    whatsapp:{configured:Boolean(process.env.WHATSAPP_ACCESS_TOKEN),phone_number_configured:Boolean(process.env.WHATSAPP_PHONE_NUMBER_ID),mode:'cloud_api'},
    paytm:{configured:Boolean(process.env.PAYTM_MERCHANT_ID&&process.env.PAYTM_MERCHANT_KEY),environment:process.env.PAYTM_ENV||'STAGING',checksum_library:Boolean(PaytmChecksum)}
  });
});

app.post('/api/integrations/meta/test',auth,async(req,res)=>{
  if(!process.env.META_ACCESS_TOKEN)return res.status(503).json({error:'Meta credentials are not configured'});
  const account=String(req.body?.ad_account_id||process.env.META_AD_ACCOUNT_ID||'').replace(/^act_/,'');
  if(!account)return res.status(400).json({error:'Meta ad account ID is required'});
  try{
    const url=`${graphBase(process.env.META_GRAPH_BASE_URL,process.env.META_GRAPH_VERSION)}/act_${encodeURIComponent(account)}`;
    const r=await fetch(url,{headers:{Authorization:`Bearer ${process.env.META_ACCESS_TOKEN}`}});
    const data=await r.json();
    if(!r.ok)return res.status(r.status).json({error:'Meta API connection failed',details:data});
    res.json({ok:true,account:data});
  }catch(e){res.status(502).json({error:'Meta API request failed'});}
});

