app.post('/api/integrations/whatsapp/send',auth,async(req,res)=>{
  if(!process.env.WHATSAPP_ACCESS_TOKEN)return res.status(503).json({error:'WhatsApp credentials are not configured'});
  const phone=String(req.body?.phone_number_id||process.env.WHATSAPP_PHONE_NUMBER_ID||'');
  const to=String(req.body?.to||'').replace(/\D/g,'');
  const body=String(req.body?.message||'').trim();
  if(!phone||!to||!body)return res.status(400).json({error:'phone_number_id, to and message are required'});
  if(body.length>4096)return res.status(400).json({error:'Message is too long'});
  try{
    const url=`${graphBase(process.env.WHATSAPP_GRAPH_BASE_URL,process.env.WHATSAPP_GRAPH_VERSION)}/${encodeURIComponent(phone)}/messages`;
    const r=await fetch(url,{method:'POST',headers:{Authorization:`Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`,'Content-Type':'application/json'},body:JSON.stringify({messaging_product:'whatsapp',to,type:'text',text:{body}})});
    const data=await r.json();
    if(!r.ok)return res.status(r.status).json({error:'WhatsApp send failed',details:data});
    res.json({ok:true,result:data});
  }catch(e){res.status(502).json({error:'WhatsApp send request failed'});}
});

app.post('/api/integrations/paytm/create-order',auth,async(req,res)=>{
  const mid=process.env.PAYTM_MERCHANT_ID,key=process.env.PAYTM_MERCHANT_KEY;
  if(!mid||!key)return res.status(503).json({error:'Paytm credentials are not configured'});
  if(!PaytmChecksum)return res.status(503).json({error:'Paytm checksum package is not installed'});
  const amount=Number(req.body?.amount);
  if(!Number.isFinite(amount)||amount<=0)return res.status(400).json({error:'Valid positive amount is required'});
  const orderId=String(req.body?.order_id||`AJM_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`).replace(/[^A-Za-z0-9_-]/g,'').slice(0,50);
  const body={requestType:'Payment',mid,websiteName:process.env.PAYTM_WEBSITE||'WEBSTAGING',orderId,txnAmount:{value:amount.toFixed(2),currency:'INR'},userInfo:{custId:String(req.user.id)}};
  if(process.env.PAYTM_CALLBACK_URL)body.callbackUrl=process.env.PAYTM_CALLBACK_URL;
  try{
    const signature=PaytmChecksum.generateSignature(JSON.stringify(body),key);
    const base=String(process.env.PAYTM_BASE_URL||'https://securegw-stage.paytm.in').replace(/\/$/,'');
    const url=`${base}/theia/api/v1/initiateTransaction?mid=${encodeURIComponent(mid)}&orderId=${encodeURIComponent(orderId)}`;
    const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body,head:{signature}})});
    const data=await r.json();
    if(!r.ok)return res.status(r.status).json({error:'Paytm initiate transaction failed',details:data});
    const txnToken=data?.body?.txnToken;
    if(!txnToken)return res.status(502).json({error:'Paytm did not return a transaction token',details:data});
    res.json({ok:true,order_id:orderId,mid,amount:amount.toFixed(2),txn_token:txnToken,environment:process.env.PAYTM_ENV||'STAGING'});
  }catch(e){res.status(502).json({error:'Paytm request failed'});}
});

app.post('/api/integrations/paytm/status',auth,async(req,res)=>{
  const mid=process.env.PAYTM_MERCHANT_ID,key=process.env.PAYTM_MERCHANT_KEY;
  if(!mid||!key)return res.status(503).json({error:'Paytm credentials are not configured'});
  if(!PaytmChecksum)return res.status(503).json({error:'Paytm checksum package is not installed'});
  const orderId=String(req.body?.order_id||'');
  if(!orderId)return res.status(400).json({error:'order_id is required'});
  const body={mid,orderId};
  try{
    const signature=PaytmChecksum.generateSignature(JSON.stringify(body),key);
    const base=String(process.env.PAYTM_BASE_URL||'https://securegw-stage.paytm.in').replace(/\/$/,'');
    const r=await fetch(`${base}/v3/order/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body,head:{signature}})});
    const data=await r.json();
    if(!r.ok)return res.status(r.status).json({error:'Paytm status request failed',details:data});
    res.json({ok:true,result:data});
  }catch(e){res.status(502).json({error:'Paytm status request failed'});}
});

